            raise WikiError("No change in text")
        self.pages[page]['revisions'].append((self.pages[page]['latest_revision'] + 1, text))
        self.pages[page]['authors'].add(author)
        self.pages[page]['latest_revision'] += 1

    def get_text(self, page):
