        if car["floor"] == floor:
            return

        # Passengers get out
        for rider in car["riders"]:
            self.delivered.append(rider)
        car["riders"] = []

        # Passengers get in
        while self.waiting[floor] and len(car["riders"]) < 4:
            car["riders"].append(self.waiting[floor].pop(0))

        car["floor"] = floor

    def get_car_floor(self, car_id: str) -> int:
