class LightGrid:
    def __init__(self, width: int, height: int):
        if not (isinstance(width, int) and isinstance(height, int) and width >= 1 and height >= 1):
            raise ValueError("Width and height must be integers greater than or equal to 1")
        self.width = width
        self.height = height
        self.grid = [[False] * width for _ in range(height)]

    def turn_on(self, x1: int, y1: int, x2: int, y2: int) -> None:
        self._validate_coordinates(x1, y1, x2, y2)
        for y in range(y1, y2 + 1):
            for x in range(x1, x2 + 1):
                self.grid[y][x] = True

    def turn_off(self, x1: int, y1: int, x2: int, y2: int) -> None:
        self._validate_coordinates(x1, y1, x2, y2)
        for y in range(y1, y2 + 1):
            for x in range(x1, x2 + 1):
                self.grid[y][x] = False

    def toggle(self, x1: int, y1: int, x2: int, y2: int) -> None:
        self._validate_coordinates(x1, y1, x2, y2)
        for y in range(y1, y2 + 1):
            for x in range(x1, x2 + 1):
                self.grid[y][x] = not self.grid[y][x]

    def is_on(self, x: int, y: int) -> bool:
        self._validate_coordinates(x, y, x, y)
        return self.grid[y][x]

    def get_lit_count(self) -> int:
        return sum(sum(row) for row in self.grid)

    def _validate_coordinates(self, x1: int, y1: int, x2: int, y2: int) -> None:
        if not (isinstance(x1, int) and isinstance(y1, int) and isinstance(x2, int) and isinstance(y2, int)):
