class RaceTelemetry:
    def __init__(self, laps: int):
        if laps <= 0:
            raise ValueError("Laps must be greater than 0")
        self.laps = laps
        self.cars = {}
        self.finished_cars = {}

    def add_car(self, car_id: str) -> None:
        if not car_id:
            raise ValueError("Car ID cannot be empty")
        if car_id in self.cars:
            raise TelemetryError(f"Car ID '{car_id}' already added")
        self.cars[car_id] = []

    def get_cars(self) -> list[str]:
        return list(self.cars.keys())

    def record_lap(self, car_id: str, lap_time: int) -> None:
        if car_id not in self.cars:
            raise KeyError(f"Car ID '{car_id}' not added")
        if lap_time <= 0:
            raise ValueError("Lap time must be greater than 0")
        if len(self.cars[car_id]) == self.laps:
            raise TelemetryError(f"Car ID '{car_id}' has already finished")
        self.cars[car_id].append(lap_time)

    def get_lap_times(self, car_id: str) -> list[int]:
        if car_id not in self.cars:
            raise KeyError(f"Car ID '{car_id}' not added")
        return self.cars[car_id]

    def get_results(self) -> list[tuple[str, int]]:
        results = []
        for car_id, lap_times in self.cars.items():
            total_time = sum(lap_times)
            if len(lap_times) == self.laps:
                results.append((car_id, total_time))
        results.sort(key=lambda x: x[1])
        points = [10, 6, 4, 3, 2, 1, 0]
        for i, (car_id, _) in enumerate(results):
            results[i] = (car_id, points[min(i, len(points) - 1)])
        return results
