        if x < 0 or x >= self.plateau_size or y < 0 or y >= self.plateau_size:
            raise ValueError(f"Invalid coordinates: ({x}, {y})")
        if facing not in ["north", "east", "south", "west"]:
            raise ValueError(f"Invalid facing: {facing}")
        if self.get_rover_at(x, y):
            raise RoverError(f"Cell ({x}, {y}) is already occupied")
        self.rovers[rover_id] = (x, y, facing)
        self.odometers[rover_id] = 0

    def drive(self, rover_id: str, commands: str) -> None:
        if rover_id not in self.rovers:
            raise KeyError(f"Unknown rover id: {rover_id}")
        x, y, facing = self.rovers[rover_id]
        for command in commands:
            if command == "F":
                if facing == "north":
                    y = (y + 1) % self.plateau_size
                elif facing == "east":
                    x = (x + 1) % self.plateau_size
                elif facing == "south":
                    y = (y - 1) % self.plateau_size
                elif facing == "west":
                    x = (x - 1) % self.plateau_size
                if self.get_rover_at(x, y):
                    return
                self.rovers[rover_id] = (x, y, facing)
                self.odometers[rover_id] += 1
            elif command == "B":
                if facing == "north":
                    y = (y - 1) % self.plateau_size
                elif facing == "east":
                    x = (x - 1) % self.plateau_size
                elif facing == "south":
                    y = (y + 1) % self.plateau_size
                elif facing == "west":
                    x = (x + 1) % self.plateau_size
                if self.get_rover_at(x, y):
                    return
                self.rovers[rover_id] = (x, y, facing)
                self.odometers[rover_id] += 1
            elif command == "L":
                if facing == "north":
                    facing = "west"
                elif facing == "east":
                    facing = "north"
                elif facing == "south":
                    facing = "east"
                elif facing == "west":
                    facing = "south"
                self.rovers[rover_id] = (x, y, facing)
            elif command == "R":
                if facing == "north":
                    facing = "east"
                elif facing == "east":
                    facing = "south"
                elif facing == "south":
                    facing = "west"
                elif facing == "west":
                    facing = "north"
                self.rovers[rover_id] = (x, y, facing)
            else:
                raise ValueError(f"Invalid command: {command}")

    def get_location(self, rover_id: str) -> tuple[int, int, str]:
        if rover_id not in self.rovers:
            raise KeyError(f"Unknown rover id: {rover_id}")
        return self.rovers[rover_id]

    def get_rover_at(self, x: int, y: int) -> str | None:
        if x < 0 or x >= self.plateau_size or y < 0 or y >= self.plateau_size:
            raise ValueError(f"Invalid coordinates: ({x}, {y})")
        for rover_id, (rx, ry, _) in self.rovers.items():
            if rx == x and ry == y:
                return rover_id
        return None

    def get_odometer(self, rover_id: str) -> int:
        if rover_id not in self.rovers:
            raise KeyError(f"Unknown rover id: {rover_id}")
        return self.odometers[rover_id]

    def get_rovers(self) -> list[str]:
        return list(self.rovers.keys())
