class BillingSystem:
    def __init__(self):
        self.plans = {}
        self.subscriptions = {}
        self.charges = {}

    def add_plan(self, plan_id: str, price: int) -> None:
        if not plan_id:
            raise ValueError("Plan ID cannot be empty")
        if price <= 0:
            raise ValueError("Price must be greater than 0")
        if plan_id in self.plans:
            raise BillingError(f"Plan ID '{plan_id}' already exists")
        self.plans[plan_id] = price

    def subscribe(self, customer: str, plan_id: str) -> None:
        if not customer:
            raise ValueError("Customer cannot be empty")
        if plan_id not in self.plans:
            raise KeyError(f"Plan ID '{plan_id}' not found")
        if customer in self.subscriptions:
            raise BillingError(f"Customer '{customer}' is already subscribed")
        self.subscriptions[customer] = plan_id
        self.charges[customer] = []

    def change_plan(self, customer: str, plan_id: str) -> None:
        if customer not in self.subscriptions:
            raise KeyError(f"Customer '{customer}' not found")
        if plan_id not in self.plans:
            raise KeyError(f"Plan ID '{plan_id}' not found")
        if self.subscriptions[customer] == plan_id:
            raise BillingError(f"Customer '{customer}' is already on plan '{plan_id}'")
        current_plan = self.subscriptions[customer]
        self.subscriptions[customer] = plan_id
        if self.plans[plan_id] > self.plans[current_plan]:
            self.charges[customer].append(self.plans[plan_id] - self.plans[current_plan])

    def cancel(self, customer: str) -> None:
        if customer not in self.subscriptions:
            raise KeyError(f"Customer '{customer}' not found")
        del self.subscriptions[customer]
        del self.charges[customer]

    def run_cycle(self) -> int:
        total_charged = 0
        for customer, plan_id in self.subscriptions.items():
            charge = self.plans[plan_id]
            self.charges[customer].append(charge)
            total_charged += charge
        return total_charged

    def get_plan(self, customer: str) -> str:
        if customer not in self.subscriptions:
            raise KeyError(f"Customer '{customer}' not found")
        return self.subscriptions[customer]

    def get_charges(self, customer: str) -> list[int]:
        if customer not in self.subscriptions:
            raise KeyError(f"Customer '{customer}' not found")
        return self.charges[customer]
