class ClockError(Exception):
    pass


class TimeClock:
    def __init__(self):
        self.employees = {}

    def add_employee(self, employee_id: str) -> None:
        if not employee_id:
            raise ValueError("Employee ID cannot be empty")
        if employee_id in self.employees:
            raise ClockError(f"Employee {employee_id} already exists")
        self.employees[employee_id] = {
            'open_shift': None,
            'shifts': []
        }

    def clock_in(self, employee_id: str, minute: int) -> None:
        self._validate_employee(employee_id)
        if not isinstance(minute, int) or minute < 0:
            raise ValueError("Minute must be a non-negative integer")
        if self.employees[employee_id]['open_shift'] is not None:
            raise ClockError(f"Employee {employee_id} is already clocked in")
        if self.employees[employee_id]['shifts'] and minute < self.employees[employee_id]['shifts'][-1][1]:
            raise ValueError("Clock-in minute must be later than the end of the last shift")
        self.employees[employee_id]['open_shift'] = minute

    def clock_out(self, employee_id: str, minute: int) -> None:
        self._validate_employee(employee_id)
        if not isinstance(minute, int) or minute < 0:
            raise ValueError("Minute must be a non-negative integer")
        if self.employees[employee_id]['open_shift'] is None:
            raise ClockError(f"Employee {employee_id} is not clocked in")
        if minute <= self.employees[employee_id]['open_shift']:
            raise ValueError("Clock-out minute must be later than the clock-in minute")
        self.employees[employee_id]['shifts'].append((self.employees[employee_id]['open_shift'], minute))
        self.employees[employee_id]['open_shift'] = None

    def get_open_shift(self, employee_id: str) -> int | None:
